1	/**
2	 * Benny — the ONE canonical mascot model + joint rig (procedural, exported to assets/models/benny.glb).
3	 *
4	 * Contract: origin = centre of the round body, faces +Z, up +Y. Skin sphere r = 0.70 (lower half bulged
5	 * ~6 % → pear-round plush ball), fur adds ~0.15 (visual half-width ≈ 0.86). The beanie perches on the
6	 * top ~40 % of the ball (brim bottom ≈ +0.10 at the back, +0.24 at the front). Height incl. pom ≈ 2.3.
7	 * Joints: benny_root › body › { hat › pom, eyes › eyeL/eyeR, mouth, armL, armR, footL, footR }.
8	 * Meshes named fur_* receive the runtime shell-fur shader (see fur.ts); their userData carries the
9	 * fur parameters (exported as glTF extras).
10	 */
11	import * as THREE from 'three';
12	import type { BuiltModel } from '../types';
13	import {
14	  BENNY_COLORS as C,
15	  CROWN_REPEAT,
16	  blushTexture,
17	  eyeTexture,
18	  knitCrownTextures,
19	  mouthTexture,
20	  ribbedBrimTextures,
21	  soleTexture,
22	} from './textures';
23	
24	export const BENNY_DIMS = {
25	  skin: 0.7,
26	  fur: 0.12,
27	  radius: 0.8,
28	  /** lower-body bulge (radial gain at its peak) — the plush ball is widest below the brim (refs 05/07/10) */
29	  pear: 0.09,
30	  /** lower-half vertical stretch at the bottom pole (y' = y·(1 + stretch·|y|/r) for y < 0) */
31	  stretch: 0.1,
32	  /** front of the beanie raised (rad, about X). Small, so the back brim stays high on the ball in rear views */
33	  hatTilt: -0.06,
34	  brimBottom: 0.24, // hat-local
35	  /** cuff outer radius ≈ the fluffy body half-width (rear refs 05/07/09/10: cuff as wide as the body) */
36	  brimR: 0.8,
37	  /** folded cuff band height (ref 05 at ≈12° camera elevation: 51 px band on a 293 px wide cuff ≈ 0.17) */
38	  cuffH: 0.265,
39	  /** crown dome height above its base (inside the cuff). Short: in the rear refs the visible crown (W·P·W) is
40	   *  ≈ 0.27 × the cuff width and the pom-pom sits right on it (the old 0.54 crown showed a big purple cap) */
41	  crownH: 0.47,
42	  /** pom-pom core radius; the shell fur adds ≈ 0.08 visible → ≈ 0.5 × the cuff width (ref 05: 140–150 px / 293) */
43	  pomR: 0.33,
44	};
45	
46	/**
47	 * Body skin deformation of a point `v` on the r = skin sphere: the lower half is stretched down a little
48	 * and bulged radially (strongest at the sides/back, faded out on the face so eyes, blush and mouth keep
49	 * their places) → a big round plush ball below the beanie.
50	 */
51	function deformBody(v: THREE.Vector3, out: THREE.Vector3): THREE.Vector3 {
52	  const r = BENNY_DIMS.skin;
53	  const zf = THREE.MathUtils.smoothstep(v.z / r, 0.1, 0.75);
54	  const k = 1 + BENNY_DIMS.pear * Math.exp(-(((v.y + 0.24) / 0.38) ** 2)) * (1 - 0.8 * zf);
55	  const y = v.y < 0 ? v.y * (1 + (BENNY_DIMS.stretch * -v.y) / r) : v.y;
56	  return out.set(v.x * k, y, v.z * k);
57	}
58	
59	const FACE_DIR = new THREE.Vector3(0, 0.05, 1).normalize();
60	
61	function named<T extends THREE.Object3D>(o: T, name: string): T {
62	  o.name = name;
63	  return o;
64	}
65	
66	function joint(name: string, x = 0, y = 0, z = 0): THREE.Object3D {
67	  const j = new THREE.Object3D();
68	  j.name = name;
69	  j.position.set(x, y, z);
70	  return j;
71	}
72	
73	/** hemisphere dome facing +Z with planar UVs (u,v = x,y mapped to 0..1) */
74	function domeGeometry(r: number, wSeg = 32, hSeg = 14): THREE.BufferGeometry {
75	  const g = new THREE.SphereGeometry(r, wSeg, hSeg, 0, Math.PI * 2, 0, Math.PI / 2);
76	  g.rotateX(Math.PI / 2); // +Y pole → +Z
77	  const p = g.attributes.position as THREE.BufferAttribute;
78	  const uv = g.attributes.uv as THREE.BufferAttribute;
79	  for (let i = 0; i < p.count; i++) uv.setXY(i, p.getX(i) / (2 * r) + 0.5, p.getY(i) / (2 * r) + 0.5);
80	  return g;
81	}
82	
83	/** a rectangular decal draped onto a sphere of radius `radius` around the origin, centred on `dir` */
84	function sphereDecal(dir: THREE.Vector3, w: number, h: number, radius: number, seg = 10): THREE.BufferGeometry {
85	  const g = new THREE.PlaneGeometry(w, h, seg, seg);
86	  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), dir.clone().normalize());
87	  const p = g.attributes.position as THREE.BufferAttribute;
88	  const v = new THREE.Vector3();
89	  for (let i = 0; i < p.count; i++) {
90	    v.set(p.getX(i), p.getY(i), radius).applyQuaternion(q).setLength(radius);
91	    p.setXYZ(i, v.x, v.y, v.z);
92	  }
93	  g.computeVertexNormals();
94	  return g;
95	}
96	
97	function std(o: THREE.MeshStandardMaterialParameters): THREE.MeshStandardMaterial {
98	  return new THREE.MeshStandardMaterial(o);
99	}
100	
101	function furData(o: {
102	  length: number;
103	  density: number;
104	  shells: number;
105	  root: string;
106	  tip: string;
107	  bald?: [number, number, number, number]; // dir (mesh-local) + dot threshold → no fur beyond it
108	  short?: [number, number, number, number, number, number]; // dir + t0,t1 + min factor
109	  gravity?: number;
110	}) {
111	  return { fur: { gravity: 0.35, ...o } };
112	}
113	
114	function lathe(points: [number, number][], segs: number, v0: number, v1: number, uRepeat = 1): THREE.LatheGeometry {
115	  const g = new THREE.LatheGeometry(points.map(([r, y]) => new THREE.Vector2(r, y)), segs);
116	  // re-map v to height so stripes are linear in height; u (around) optionally tiles the texture
117	  const p = g.attributes.position as THREE.BufferAttribute;
118	  const uv = g.attributes.uv as THREE.BufferAttribute;
119	  for (let i = 0; i < p.count; i++) uv.setXY(i, uv.getX(i) * uRepeat, (p.getY(i) - v0) / (v1 - v0));
120	  return g;
121	}
122	
123	function starShape(outer: number, inner: number): THREE.Shape {
124	  const s = new THREE.Shape();
125	  for (let i = 0; i < 10; i++) {
126	    const a = Math.PI / 2 + (i * Math.PI) / 5;
127	    const r = i % 2 === 0 ? outer : inner;
128	    const x = Math.cos(a) * r, y = Math.sin(a) * r;
129	    if (i === 0) s.moveTo(x, y); else s.lineTo(x, y);
130	  }
131	  s.closePath();
132	  return s;
133	}
134	
135	export function buildBenny(): BuiltModel {
136	  const D = BENNY_DIMS;
137	  const root = named(new THREE.Group(), 'benny_root');
138	  const body = joint('body');
139	  root.add(body);
140	
141	  // ---------------- body (fur) ----------------
142	  const hatUp = new THREE.Vector3(0, 1, 0).applyAxisAngle(new THREE.Vector3(1, 0, 0), D.hatTilt);
143	  const bodyMat = std({ color: C.pinkSkin, roughness: 0.92, metalness: 0 });
144	  const bodyGeo = new THREE.SphereGeometry(D.skin, 48, 36);
145	  {
146	    // pear-round plush ball. Normals come from finite differences of the deformation on the sphere
147	    // (position-only, so UV-seam / pole duplicates get identical normals and the shell fur stays closed)
148	    const p = bodyGeo.attributes.position as THREE.BufferAttribute;
149	    const n = bodyGeo.attributes.normal as THREE.BufferAttribute;
150	    const d = new THREE.Vector3(), t1 = new THREE.Vector3(), t2 = new THREE.Vector3();
151	    const a = new THREE.Vector3(), b = new THREE.Vector3(), c = new THREE.Vector3(), e = new THREE.Vector3();
152	    const s = new THREE.Vector3(), o = new THREE.Vector3();
153	    const eps = 1e-3;
154	    for (let i = 0; i < p.count; i++) {
155	      d.set(p.getX(i), p.getY(i), p.getZ(i)).normalize();
156	      t1.set(0, 1, 0).cross(d);
157	      if (t1.lengthSq() < 1e-6) t1.set(1, 0, 0).cross(d);
158	      t1.normalize();
159	      t2.crossVectors(d, t1).normalize();
160	      const at = (u: number, w: number, out: THREE.Vector3) =>
161	        deformBody(s.copy(d).addScaledVector(t1, u).addScaledVector(t2, w).setLength(D.skin), out);
162	      at(eps, 0, a); at(-eps, 0, b); at(0, eps, c); at(0, -eps, e);
163	      a.sub(b); c.sub(e);
164	      const nn = o.crossVectors(a, c).normalize();
165	      if (nn.dot(d) < 0) nn.negate();
166	      n.setXYZ(i, nn.x, nn.y, nn.z);
167	      deformBody(s.copy(d).multiplyScalar(D.skin), a);
168	      p.setXYZ(i, a.x, a.y, a.z);
169	    }
170	  }
171	  const bodyMesh = named(new THREE.Mesh(bodyGeo, bodyMat), 'fur_body');
172	  bodyMesh.userData = furData({
173	    length: D.fur,
174	    density: 64,
175	    shells: 20,
176	    root: C.pinkRoot,
177	    tip: C.pinkTip,
178	    // bald under the beanie: dot(normal, hatUp) > brimBottom/skin (+ a little overlap)
179	    bald: [hatUp.x, hatUp.y, hatUp.z, (D.brimBottom + 0.03) / D.skin],
180	    short: [FACE_DIR.x, FACE_DIR.y, FACE_DIR.z, 0.74, 0.93, 0.26],
181	    gravity: 0.1,
182	  });
183	  body.add(bodyMesh);
184	
185	  // ---------------- face ----------------
186	  const eyes = joint('eyes');
187	  body.add(eyes);
188	  const eyeR = 0.178;
189	  const eyeGeo = domeGeometry(eyeR, 32, 12);
190	  eyeGeo.scale(1, 1.06, 0.55);
191	  const eyeMatHappy = std({ map: eyeTexture('happy'), roughness: 0.12, metalness: 0 });
192	  const eyeMatDizzy = std({ map: eyeTexture('dizzy'), roughness: 0.12, metalness: 0 });
193	  const lashMat = std({ color: '#241036', roughness: 0.5 });
194	  for (const side of [1, -1] as const) {
195	    // side +1 = Benny's left (+X), −1 = right (−X)
196	    const dir = new THREE.Vector3(0.34 * side, -0.005, 0.94).normalize();
197	    const e = joint(side > 0 ? 'eyeL' : 'eyeR');
198	    e.position.copy(dir).multiplyScalar(0.665);
199	    e.lookAt(dir.clone().multiplyScalar(5));
200	    eyes.add(e);
201	    const happy = named(new THREE.Mesh(eyeGeo, eyeMatHappy), side > 0 ? 'eyeL_happy' : 'eyeR_happy');
202	    const dizzy = named(new THREE.Mesh(eyeGeo, eyeMatDizzy), side > 0 ? 'eyeL_dizzy' : 'eyeR_dizzy');
203	    dizzy.visible = false;
204	    e.add(happy, dizzy);
205	    // two little upper lashes on the outer corner
206	    for (const [a, len] of [[0.5, 0.075], [0.85, 0.065]] as const) {
207	      // eye-local: +X of the eye frame points to Benny's left when looking from the front
208	      const ang = side > 0 ? a : Math.PI - a;
209	      const lash = new THREE.Mesh(new THREE.ConeGeometry(0.014, len, 6), lashMat);
210	      lash.position.set(Math.cos(ang) * eyeR * 1.0, Math.sin(ang) * eyeR * 1.05, 0.045);
211	      lash.rotation.z = ang - Math.PI / 2;
212	      lash.translateY(len * 0.45);
213	      lash.name = `lash_${side > 0 ? 'L' : 'R'}_${a}`;
214	      e.add(lash);
215	    }
216	  }
217	  // blush
218	  const blushMat = std({ map: blushTexture(), transparent: true, depthWrite: false, roughness: 0.8 });
219	  for (const side of [1, -1]) {
220	    const m = named(new THREE.Mesh(sphereDecal(new THREE.Vector3(0.6 * side, -0.24, 0.78), 0.3, 0.19, 0.775), blushMat), side > 0 ? 'blushL' : 'blushR');
221	    m.renderOrder = 2;
222	    body.add(m);
223	  }
224	  // nose
225	  const nose = named(new THREE.Mesh(new THREE.SphereGeometry(0.03, 12, 8), std({ color: '#7d2550', roughness: 0.35 })), 'nose');
226	  nose.position.copy(new THREE.Vector3(0, -0.13, 1).normalize().multiplyScalar(0.738));
227	  nose.scale.set(1.3, 0.9, 0.8);
228	  body.add(nose);
229	  // mouth decals (alpha-tested)
230	  const mouth = joint('mouth');
231	  body.add(mouth);
232	  const mouthDir = new THREE.Vector3(0, -0.34, 0.94);
233	  for (const kind of ['happy', 'dizzy', 'peek'] as const) {
234	    const w = kind === 'dizzy' ? 0.19 : 0.29;
235	    const m = named(
236	      new THREE.Mesh(
237	        sphereDecal(mouthDir, w, w, 0.752, 8),
238	        std({ map: mouthTexture(kind), alphaTest: 0.5, roughness: 0.4, side: THREE.DoubleSide }),
239	      ),
240	      `mouth_${kind}`,
241	    );
242	    m.visible = kind === 'happy';
243	    mouth.add(m);
244	  }
245	
246	  // ---------------- arms ----------------
247	  const armMat = std({ color: C.pinkSkin, roughness: 0.92 });
248	  const palmTex = soleTexture('hand');
249	  for (const side of [1, -1] as const) {
250	    // round paw nubs stick out left/right just under the cuff (rear refs 05/07/10: centres ≈ 0.15 × the cuff
251	    // width below its bottom edge). Kept low enough that the swim paddle (z up to +0.45) clears the cuff.
252	    const a = joint(side > 0 ? 'armL' : 'armR', 0.7 * side, -0.01, 0.03);
253	    body.add(a);
254	    const phi = 1.15 * side;
255	    const dir = new THREE.Vector3(Math.sin(phi), -Math.cos(phi), 0);
256	    const g = new THREE.SphereGeometry(0.135, 20, 14);
257	    g.scale(1, 1.25, 1);
258	    const arm = named(new THREE.Mesh(g, armMat), side > 0 ? 'fur_armL' : 'fur_armR');
259	    arm.position.copy(dir).multiplyScalar(0.16);
260	    arm.rotation.z = phi;
261	    arm.userData = furData({ length: 0.08, density: 84, shells: 12, root: C.pinkRoot, tip: C.pinkTip, gravity: 0.15 });
262	    a.add(arm);
263	    const palm = named(
264	      new THREE.Mesh(new THREE.CircleGeometry(0.07, 24), std({ map: palmTex, roughness: 0.6 })),
265	      side > 0 ? 'palmL' : 'palmR',
266	    );
267	    palm.position.copy(dir).multiplyScalar(0.25).add(new THREE.Vector3(0, -0.01, 0.105));
268	    palm.rotation.x = -0.25;
269	    a.add(palm);
270	  }
271	
272	  // ---------------- feet ----------------
273	  const footTex = soleTexture('foot');
274	  for (const side of [1, -1] as const) {
275	    const f = joint(side > 0 ? 'footL' : 'footR', 0.31 * side, -0.65, 0.27);
276	    body.add(f);
277	    const g = new THREE.SphereGeometry(0.2, 22, 16);
278	    g.scale(1, 0.82, 1.12);
279	    const foot = named(new THREE.Mesh(g, armMat), side > 0 ? 'fur_footL' : 'fur_footR');
280	    foot.position.set(0, -0.03, 0.06);
281	    foot.userData = furData({
282	      length: 0.06, density: 70, shells: 8, root: C.pinkRoot, tip: C.pinkTip, gravity: 0.1,
283	      bald: [0, -0.55, 0.83, 0.55],
284	    });
285	    f.add(foot);
286	    const sole = named(new THREE.Mesh(new THREE.CircleGeometry(0.165, 28), std({ map: footTex, roughness: 0.55 })), side > 0 ? 'soleL' : 'soleR');
287	    sole.scale.set(1, 1.08, 1);
288	    sole.position.set(0, -0.085, 0.235);
289	    // faces forward and a little down (lookAt in foot-local space: sole has no parent yet)
290	    sole.lookAt(sole.position.clone().add(new THREE.Vector3(0, -0.55, 0.83)));
291	    f.add(sole);
292	  }
293	
294	  // ---------------- knitted beanie ----------------
295	  const hat = joint('hat');
296	  hat.rotation.x = D.hatTilt;
297	  body.add(hat);
298	  const yb = D.brimBottom;
299	  const yt = yb + D.cuffH; // cuff top
300	  const bk = D.brimR / 0.778; // profile scale (profiles were authored for a 0.778 brim)
301	  const brimTex = ribbedBrimTextures();
302	  const brimMat = std({ map: brimTex.map, normalMap: brimTex.normalMap, normalScale: new THREE.Vector2(1.25, 1.25), roughness: 0.86 });
303	  // inner lip hugs the skin at the brim height (sphere radius there ≈ 0.68)
304	  const lip = Math.sqrt(D.skin * D.skin - yb * yb) + 0.012;
305	  // chunky rolled cuff: rounded bottom and top edges, slight belly in the middle
306	  const brim = named(
307	    new THREE.Mesh(
308	      lathe(
309	        [
310	          [lip, yb + 0.01],
311	          [0.725 * bk, yb - 0.008],
312	          [0.758 * bk, yb + 0.02],
313	          [0.776 * bk, yb + 0.07],
314	          [0.781 * bk, yb + 0.15],
315	          [0.776 * bk, yt - 0.075],
316	          [0.758 * bk, yt - 0.025],
317	          [0.725 * bk, yt - 0.003],
318	          [0.68 * bk, yt],
319	        ],
320	        72,
321	        yb - 0.01,
322	        yt + 0.005,
323	      ),
324	      brimMat,
325	    ),
326	    'hat_brim',
327	  );
328	  // the brim texture's "v" should run across the band (ribs vertical): lathe u = around ✓
329	  hat.add(brim);
330	  const crownTex = knitCrownTextures();
331	  const crownMat = std({ map: crownTex.map, normalMap: crownTex.normalMap, normalScale: new THREE.Vector2(1.3, 1.3), roughness: 0.9 });
332	  // crown dome: starts inside the cuff and is narrower than it (the chunky cuff flares out, refs 04–10), with
333	  // an elliptic profile r = R0·√(1 − (y/H)²) that tapers to the pom-pom (which covers the apex).
334	  // v = height → horizontal knit stripes.
335	  const crownY0 = yt - 0.045;
336	  const R0 = 0.705 * bk;
337	  const crownProfile: [number, number][] = [];
338	  for (const t of [0, 0.08, 0.16, 0.25, 0.34, 0.43, 0.52, 0.6, 0.68, 0.75, 0.81, 0.86, 0.9, 0.935, 0.96, 0.98, 0.993, 1]) {
339	    crownProfile.push([R0 * Math.sqrt(Math.max(0, 1 - t * t)), crownY0 + t * D.crownH]);
340	  }
341	  const crown = named(
342	    new THREE.Mesh(lathe(crownProfile, 72, crownY0, crownY0 + D.crownH, CROWN_REPEAT), crownMat),
343	    'hat_crown',
344	  );
345	  hat.add(crown);
346	  // gold star on the cuff's top edge, rear-RIGHT (−X): image-right of centre in the rear gameplay views
347	  // (ref 05: star centre at ≈ 0.64 of the cuff half-width → 140° from the front). Its face is turned toward
348	  // the back (normal 160° from the front, tilted 12° up) so the ride cameras behind/above see it face-on
349	  // instead of edge-on; the inner points tuck into the knit, the outer points stand proud like a sewn badge.
350	  const starGeo = new THREE.ExtrudeGeometry(starShape(0.205, 0.1), {
351	    depth: 0.04,
352	    bevelEnabled: true,
353	    bevelThickness: 0.03,
354	    bevelSize: 0.024,
355	    bevelSegments: 3,
356	  });
357	  starGeo.center();
358	  const star = named(
359	    new THREE.Mesh(starGeo, std({ color: C.gold, metalness: 0.12, roughness: 0.3, emissive: '#ffb800', emissiveIntensity: 0.22 })),
360	    'hat_star',
361	  );
362	  const sa = THREE.MathUtils.degToRad(146);
363	  const starPos = new THREE.Vector3(-Math.sin(sa) * (D.brimR + 0.02), yt + 0.01, Math.cos(sa) * (D.brimR + 0.02));
364	  const na = THREE.MathUtils.degToRad(160), tilt = THREE.MathUtils.degToRad(12);
365	  const starN = new THREE.Vector3(-Math.sin(na) * Math.cos(tilt), Math.sin(tilt), Math.cos(na) * Math.cos(tilt));
366	  star.position.copy(starPos);
367	  star.lookAt(starPos.clone().add(starN));
368	  star.rotateZ(-0.14);
369	  hat.add(star);
370	  // big fluffy-round pom-pom, sunk onto the crown apex (≈ 0.5 × the cuff width, refs 04/05/07/09/10)
371	  const pom = joint('pom', 0, crownY0 + D.crownH + 0.04, -0.03);
372	  hat.add(pom);
373	  const pomMesh = named(new THREE.Mesh(new THREE.SphereGeometry(D.pomR, 32, 24), std({ color: C.pomRoot, roughness: 0.95 })), 'fur_pom');
374	  // short, dense strands with little droop → a round plush ball rather than a spiky urchin
375	  pomMesh.userData = furData({ length: 0.1, density: 96, shells: 16, root: C.pomRoot, tip: C.pomTip, gravity: 0.05 });
376	  pom.add(pomMesh);
377	
378	  const animations = buildClips();
379	  return { scene: root, animations };
380	}
381	
382	// ------------------------------------------------------------------ clips
383	type E3 = [number, number, number];
384	const q = (e: E3) => new THREE.Quaternion().setFromEuler(new THREE.Euler(e[0], e[1], e[2]));
385	
386	function qTrack(node: string, times: number[], eulers: E3[]): THREE.QuaternionKeyframeTrack {
387	  const vals: number[] = [];
388	  eulers.forEach((e) => vals.push(...q(e).toArray()));
389	  return new THREE.QuaternionKeyframeTrack(`${node}.quaternion`, times, vals);
390	}
391	function vTrack(node: string, prop: 'position' | 'scale', times: number[], vecs: E3[]): THREE.VectorKeyframeTrack {
392	  return new THREE.VectorKeyframeTrack(`${node}.${prop}`, times, vecs.flat());
393	}
394	function loop(n: number, dur: number): number[] {
395	  return Array.from({ length: n + 1 }, (_, i) => (i / n) * dur);
396	}
397	
398	const ARM_L: E3 = [0.7, -0.08, 0.03];
399	const ARM_R: E3 = [-0.7, -0.08, 0.03];
400	const FOOT_L: E3 = [0.31, -0.65, 0.27];
401	const FOOT_R: E3 = [-0.31, -0.65, 0.27];
402	
403	function buildClips(): THREE.AnimationClip[] {
404	  const N = 12;
405	  const tau = Math.PI * 2;
406	  // idle
407	  const ti = loop(N, 2.4);
408	  const idle = new THREE.AnimationClip('idle', 2.4, [
409	    vTrack('body', 'position', ti, ti.map((t) => [0, Math.sin((t / 2.4) * tau) * 0.015, 0])),
410	    qTrack('armL', ti, ti.map((t) => [0, 0, Math.sin((t / 2.4) * tau) * 0.08])),
411	    qTrack('armR', ti, ti.map((t) => [0, 0, -Math.sin((t / 2.4) * tau) * 0.08])),
412	    qTrack('footL', ti, ti.map(() => [0, 0, 0])),
413	    qTrack('footR', ti, ti.map(() => [0, 0, 0])),
414	    qTrack('body', ti, ti.map(() => [0, 0, 0])),
415	  ]);
416	  // swim — paws paddle, feet kick, body bobs (0.6 s loop)
417	  const D = 0.6;
418	  const ts = loop(N, D);
419	  const ph = (t: number) => (t / D) * tau;
420	  const swim = new THREE.AnimationClip('swim', D, [
421	    vTrack('body', 'position', ts, ts.map((t) => [0, Math.abs(Math.sin(ph(t))) * 0.04 - 0.01, 0])),
422	    qTrack('body', ts, ts.map((t) => [Math.sin(ph(t) * 2) * 0.03, 0, Math.sin(ph(t)) * 0.05])),
423	    qTrack('armL', ts, ts.map((t) => [Math.sin(ph(t)) * 0.75, 0, 0.25 + Math.cos(ph(t)) * 0.2])),
424	    qTrack('armR', ts, ts.map((t) => [Math.sin(ph(t) + Math.PI) * 0.75, 0, -0.25 - Math.cos(ph(t) + Math.PI) * 0.2])),
425	    qTrack('footL', ts, ts.map((t) => [Math.sin(ph(t) + Math.PI) * 0.5, 0, 0])),
426	    qTrack('footR', ts, ts.map((t) => [Math.sin(ph(t)) * 0.5, 0, 0])),
427	  ]);
428	  // tumble — paws flail up, feet kick fast (caller spins the root)
429	  const T = 1.0;
430	  const tt = loop(N, T);
431	  const pt = (t: number) => (t / T) * tau;
432	  const tumble = new THREE.AnimationClip('tumble', T, [
433	    vTrack('body', 'position', tt, tt.map(() => [0, 0, 0])),
434	    qTrack('body', tt, tt.map((t) => [0, 0, Math.sin(pt(t)) * 0.1])),
435	    qTrack('armL', tt, tt.map((t) => [Math.sin(pt(t) * 2) * 0.4, 0, 1.25 + Math.sin(pt(t) * 3) * 0.3])),
436	    qTrack('armR', tt, tt.map((t) => [Math.cos(pt(t) * 2) * 0.4, 0, -1.25 - Math.cos(pt(t) * 3) * 0.3])),
437	    qTrack('footL', tt, tt.map((t) => [Math.sin(pt(t) * 3) * 0.6, 0, 0.2])),
438	    qTrack('footR', tt, tt.map((t) => [Math.sin(pt(t) * 3 + Math.PI) * 0.6, 0, -0.2])),
439	  ]);
440	  // peek — paws hold the towel edge, gentle sway (scene 01)
441	  const P = 2.0;
442	  const tp = loop(N, P);
443	  const pp = (t: number) => (t / P) * tau;
444	  const peek = new THREE.AnimationClip('peek', P, [
445	    vTrack('body', 'position', tp, tp.map((t) => [0, 0.03 + Math.sin(pp(t)) * 0.02, 0])),
446	    qTrack('body', tp, tp.map((t) => [0.04, 0, Math.sin(pp(t)) * 0.07])),
447	    qTrack('armL', tp, tp.map((t) => [-1.15 + Math.sin(pp(t) * 2) * 0.05, 0, 0.35])),
448	    qTrack('armR', tp, tp.map((t) => [-1.15 + Math.cos(pp(t) * 2) * 0.05, 0, -0.35])),
449	    qTrack('footL', tp, tp.map(() => [0, 0, 0])),
450	    qTrack('footR', tp, tp.map(() => [0, 0, 0])),
451	  ]);
452	  void ARM_L; void ARM_R; void FOOT_L; void FOOT_R;
453	  return [idle, swim, tumble, peek];
454	}
