1	/**
2	 * Real-time shell-texturing fur for Benny (mobile-safe, one draw call per furry part).
3	 *
4	 * Each fur_* mesh becomes an InstancedMesh with `shells` instances; gl_InstanceID selects the
5	 * shell layer, which is pushed out along the normal (plus a little gravity droop). A hashed 3-D
6	 * strand grid decides per-fragment whether a strand still exists at that height (tapering strands),
7	 * so the fur keeps a fluffy silhouette from every angle. Built on MeshStandardMaterial via
8	 * onBeforeCompile so scene lighting, IBL and fog all still apply.
9	 */
10	import * as THREE from 'three';
11	
12	export interface FurParams {
13	  length: number;
14	  density: number;
15	  shells: number;
16	  root: string;
17	  tip: string;
18	  gravity?: number;
19	  bald?: [number, number, number, number];
20	  short?: [number, number, number, number, number, number];
21	}
22	
23	export interface FurHandle {
24	  mesh: THREE.InstancedMesh;
25	  material: THREE.MeshStandardMaterial;
26	  uniforms: { uTime: { value: number }; uWind: { value: THREE.Vector3 } };
27	}
28	
29	export function makeFur(src: THREE.Mesh, p: FurParams): FurHandle {
30	  const shells = Math.max(2, Math.round(p.shells));
31	  const uniforms = {
32	    uFurLen: { value: p.length },
33	    uDensity: { value: p.density },
34	    uRoot: { value: new THREE.Color(p.root) },
35	    uTip: { value: new THREE.Color(p.tip) },
36	    uGravity: { value: p.gravity ?? 0.3 },
37	    uBald: { value: new THREE.Vector4(...(p.bald ?? [0, 1, 0, 2])) },
38	    uShortDir: { value: new THREE.Vector3(...((p.short?.slice(0, 3) as [number, number, number]) ?? [0, 0, 1])) },
39	    uShort: { value: new THREE.Vector3(p.short?.[3] ?? 2, p.short?.[4] ?? 3, p.short?.[5] ?? 1) },
40	    uTime: { value: 0 },
41	    uWind: { value: new THREE.Vector3() },
42	  };
43	  const material = new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 0.9, metalness: 0 });
44	  material.onBeforeCompile = (shader) => {
45	    Object.assign(shader.uniforms, uniforms);
46	    shader.vertexShader = shader.vertexShader
47	      .replace(
48	        '#include <common>',
49	        `#include <common>
50	        uniform float uFurLen; uniform float uGravity; uniform vec4 uBald;
51	        uniform vec3 uShortDir; uniform vec3 uShort; uniform float uTime; uniform vec3 uWind;
52	        varying float vLayer; varying vec3 vBase; varying float vLenMask;`,
53	      )
54	      .replace(
55	        '#include <begin_vertex>',
56	        `#include <begin_vertex>
57	        vLayer = float(gl_InstanceID) / float(${shells - 1});
58	        vec3 nrm = normalize(objectNormal);
59	        float bald = 1.0 - smoothstep(uBald.w - 0.04, uBald.w + 0.01, dot(nrm, normalize(uBald.xyz)));
60	        float sh = mix(1.0, uShort.z, smoothstep(uShort.x, uShort.y, dot(nrm, normalize(uShortDir))));
61	        vLenMask = bald * sh;
62	        vBase = position;
63	        float h = uFurLen * vLayer * vLenMask;
64	        transformed += nrm * h;
65	        // gravity droop + gentle wind sway grows with layer height
66	        vec3 g = vec3(0.0, -1.0, 0.0) * uGravity + uWind;
67	        g += vec3(sin(uTime * 3.0 + position.y * 9.0), 0.0, cos(uTime * 2.3 + position.x * 7.0)) * 0.06;
68	        transformed += g * uFurLen * vLayer * vLayer * vLenMask;`,
69	      );
70	    shader.fragmentShader = shader.fragmentShader
71	      .replace(
72	        '#include <common>',
73	        `#include <common>
74	        uniform float uDensity; uniform vec3 uRoot; uniform vec3 uTip;
75	        varying float vLayer; varying vec3 vBase; varying float vLenMask;
76	        float fhash(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
77	        vec3 fhash3(vec3 p) { return vec3(fhash(p), fhash(p + 17.31), fhash(p + 41.7)); }`,
78	      )
79	      .replace(
80	        '#include <color_fragment>',
81	        `#include <color_fragment>
82	        {
83	          vec3 q = vBase * uDensity;
84	          // clumping: strands lean toward low-frequency tuft centres as they rise → plush tufts
85	          vec3 qc = q * 0.2;
86	          vec3 cc = (floor(qc) + 0.5 + (fhash3(floor(qc)) - 0.5) * 0.7) / 0.2;
87	          q = mix(q, cc, vLayer * 0.42);
88	          vec3 cell = floor(q);
89	          float best = 10.0; float hgt = 0.0;
90	          // nearest strand among this + neighbouring cells (gives round, jittered strands)
91	          for (int k = 0; k < 8; k++) {
92	            vec3 o = vec3(float(k & 1), float((k >> 1) & 1), float((k >> 2) & 1));
93	            vec3 c = floor(q - 0.5) + o;
94	            vec3 jp = c + 0.5 + (fhash3(c) - 0.5) * 0.8;
95	            float d = length(q - jp);
96	            if (d < best) { best = d; hgt = fhash(c * 1.7 + 3.1); }
97	          }
98	          float layer = vLayer;
99	          if (layer > 0.001) {
100	            if (vLenMask < 0.05) discard;
101	            float strandH = 0.55 + 0.45 * hgt;
102	            float radius = 0.78 * (1.0 - 0.85 * layer / strandH);
103	            if (layer > strandH || best > radius) discard;
104	          }
105	          float ao = mix(0.55, 1.0, smoothstep(0.0, 0.9, layer));
106	          diffuseColor.rgb = mix(uRoot, uTip, smoothstep(0.0, 1.0, layer)) * ao * (0.92 + 0.16 * hgt);
107	        }`,
108	      )
109	      .replace(
110	        '#include <emissivemap_fragment>',
111	        `#include <emissivemap_fragment>
112	        totalEmissiveRadiance += diffuseColor.rgb * 0.10 * vLayer;`,
113	      );
114	  };
115	  material.customProgramCacheKey = () => `benny-fur-${shells}`;
116	
117	  const mesh = new THREE.InstancedMesh(src.geometry, material, shells);
118	  const I = new THREE.Matrix4();
119	  for (let i = 0; i < shells; i++) mesh.setMatrixAt(i, I);
120	  mesh.instanceMatrix.needsUpdate = true;
121	  mesh.name = src.name;
122	  mesh.position.copy(src.position);
123	  mesh.quaternion.copy(src.quaternion);
124	  mesh.scale.copy(src.scale);
125	  mesh.frustumCulled = false;
126	  return { mesh, material, uniforms };
127	}
