1	/**
2	 * Runtime Benny: loads the canonical assets/models/benny.glb, upgrades fur_* meshes to shell fur,
3	 * and drives expressions + procedural secondary motion on top of the GLB clips.
4	 */
5	import * as THREE from 'three';
6	import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
7	import type { BennyRuntime } from '../types';
8	import { makeFur, type FurHandle, type FurParams } from './fur';
9	
10	const BENNY_URL = new URL('../../../assets/models/benny.glb', import.meta.url).href;
11	
12	let cached: Promise<THREE.Group> | null = null;
13	
14	function loadScene(): Promise<THREE.Group> {
15	  if (!cached) cached = new GLTFLoader().loadAsync(BENNY_URL).then((g) => {
16	    const s = g.scene as THREE.Group;
17	    s.userData.animations = g.animations;
18	    return s;
19	  });
20	  return cached;
21	}
22	
23	/** fur tier: explicit option, else `?quality=low|high`, else low on Android/iOS (same rule as the water) */
24	function defaultFurQuality(): 'high' | 'low' {
25	  if (typeof location === 'undefined') return 'high';
26	  const qp = new URLSearchParams(location.search).get('quality');
27	  const mobile = typeof navigator !== 'undefined' && /Android|iPhone|iPad/i.test(navigator.userAgent);
28	  return qp === 'low' || (qp !== 'high' && mobile) ? 'low' : 'high';
29	}
30	
31	export async function loadBenny(opts: { furQuality?: 'high' | 'low' } = {}): Promise<BennyRuntime> {
32	  const src = await loadScene();
33	  const clips: THREE.AnimationClip[] = src.userData.animations ?? [];
34	  return createBennyRuntime(src.clone(true), clips, { furQuality: opts.furQuality ?? defaultFurQuality() });
35	}
36	
37	/**
38	 * Ride height. The game places the root at water surface + radius·0.55 (≈ 0.44), which buried the lower
39	 * third of the plush ball in the opaque stream. While riding (swim ≥ 0.5, not tumbling) the model is
40	 * lifted inside the root so he sits ON the water like refs 04–10: only the bottom ≈ 0.1 of the fur and
41	 * the kicking feet are under the surface. Cinematics (01 peek, 02 tumble, 11 hide) keep the root as placed.
42	 */
43	export const BENNY_RIDE_LIFT = 0.3;
44	/** QA A/B hook: `?bennyLift=<units>` overrides the ride lift (e.g. 0 = the game's raw placement) */
45	function rideLift(): number {
46	  if (typeof location === 'undefined') return BENNY_RIDE_LIFT;
47	  const v = parseFloat(new URLSearchParams(location.search).get('bennyLift') ?? '');
48	  return Number.isFinite(v) ? THREE.MathUtils.clamp(v, 0, 0.6) : BENNY_RIDE_LIFT;
49	}
50	
51	/** Build the runtime around an already-loaded (or freshly built) Benny scene graph. */
52	export function createBennyRuntime(
53	  scene: THREE.Object3D,
54	  clips: THREE.AnimationClip[],
55	  opts: { furQuality?: 'high' | 'low' } = {},
56	): BennyRuntime {
57	  const root = new THREE.Group();
58	  root.name = 'Benny';
59	  root.add(scene);
60	
61	  // ---- fur upgrade ----
62	  const furs: FurHandle[] = [];
63	  const toReplace: THREE.Mesh[] = [];
64	  scene.traverse((o) => {
65	    const m = o as THREE.Mesh;
66	    if (m.isMesh && m.name.startsWith('fur_') && m.userData?.fur) toReplace.push(m);
67	  });
68	  for (const m of toReplace) {
69	    const p = { ...(m.userData.fur as FurParams) };
70	    if (opts.furQuality === 'low') p.shells = Math.max(6, Math.round(p.shells * 0.6));
71	    const h = makeFur(m, p);
72	    m.parent!.add(h.mesh);
73	    m.parent!.remove(m);
74	    furs.push(h);
75	  }
76	
77	  const get = (n: string) => scene.getObjectByName(n)!;
78	  const body = get('body');
79	  const pom = get('pom');
80	  const eyeL = get('eyeL');
81	  const eyeR = get('eyeR');
82	  const eyesGroup = get('eyes');
83	  const pomRest = pom.quaternion.clone();
84	
85	  // ---- animation mixer: idle ↔ swim blend, tumble / peek on demand ----
86	  const mixer = new THREE.AnimationMixer(scene);
87	  const act = (name: string) => {
88	    const c = clips.find((k) => k.name === name);
89	    return c ? mixer.clipAction(c) : null;
90	  };
91	  const aIdle = act('idle'), aSwim = act('swim'), aTumble = act('tumble'), aPeek = act('peek');
92	  for (const a of [aIdle, aSwim, aTumble, aPeek]) a?.play();
93	  const setW = (a: THREE.AnimationAction | null, w: number) => a && a.setEffectiveWeight(w);
94	
95	  let expression: 'happy' | 'dizzy' | 'peek' = 'happy';
96	  const setExpression = (e: 'happy' | 'dizzy' | 'peek') => {
97	    expression = e;
98	    for (const s of ['L', 'R']) {
99	      const h = scene.getObjectByName(`eye${s}_happy`);
100	      const d = scene.getObjectByName(`eye${s}_dizzy`);
101	      if (h) h.visible = e !== 'dizzy';
102	      if (d) d.visible = e === 'dizzy';
103	    }
104	    for (const k of ['happy', 'dizzy', 'peek']) {
105	      const m = scene.getObjectByName(`mouth_${k}`);
106	      if (m) m.visible = k === e;
107	    }
108	    eyesGroup.scale.setScalar(e === 'peek' ? 1.06 : 1);
109	  };
110	  setExpression('happy');
111	
112	  // ---- secondary motion state ----
113	  let pomAngX = 0, pomVelX = 0, pomAngZ = 0, pomVelZ = 0;
114	  let lastY = 0, lastVy = 0;
115	  let blinkT = 1.7;
116	  let lean = 0;
117	  let lift = 0;
118	  const liftMax = rideLift();
119	  const tmp = new THREE.Vector3();
120	  const qLean = new THREE.Quaternion();
121	  const qPom = new THREE.Quaternion();
122	  const eAxis = new THREE.Euler();
123	
124	  const update: BennyRuntime['update'] = (dt, st) => {
125	    dt = Math.min(dt, 1 / 20);
126	    // clip weights
127	    const tumble = !!st.tumble;
128	    const swim = tumble ? 0 : THREE.MathUtils.clamp(st.swim, 0, 1);
129	    const peek = expression === 'peek' && !tumble ? 1 : 0;
130	    setW(aTumble, tumble ? 1 : 0);
131	    setW(aPeek, peek);
132	    setW(aSwim, peek ? 0 : swim);
133	    setW(aIdle, tumble || peek ? 0 : 1 - swim);
134	    if (aSwim) aSwim.timeScale = 0.8 + Math.min(1.2, st.speed / 14);
135	    mixer.update(dt);
136	
137	    // ride height (see BENNY_RIDE_LIFT): eased so mode switches never pop
138	    const liftTarget = tumble || peek ? 0 : liftMax * THREE.MathUtils.smoothstep(swim, 0.5, 0.9);
139	    lift += (liftTarget - lift) * (1 - Math.exp(-dt * 7));
140	    scene.position.y = lift;
141	
142	    // steering lean (roll) + slight yaw into the turn
143	    lean += (THREE.MathUtils.clamp(st.steer, -1, 1) * 0.28 - lean) * Math.min(1, dt * 6);
144	    qLean.setFromEuler(eAxis.set(0, -lean * 0.6, -lean));
145	    body.quaternion.multiply(qLean);
146	
147	    // pom-pom spring: driven by vertical acceleration, steering and speed jitter
148	    root.getWorldPosition(tmp);
149	    const vy = (tmp.y - lastY) / Math.max(dt, 1e-3);
150	    const ay = THREE.MathUtils.clamp((vy - lastVy) / Math.max(dt, 1e-3), -80, 80);
151	    lastY = tmp.y; lastVy = vy;
152	    const k = 120, c = 9;
153	    const targetX = -ay * 0.004 + Math.sin(st.time * 11) * 0.03 * Math.min(1, st.speed / 12);
154	    const targetZ = lean * 0.9;
155	    pomVelX += (k * (targetX - pomAngX) - c * pomVelX) * dt;
156	    pomAngX += pomVelX * dt;
157	    pomVelZ += (k * (targetZ - pomAngZ) - c * pomVelZ) * dt;
158	    pomAngZ += pomVelZ * dt;
159	    qPom.setFromEuler(eAxis.set(THREE.MathUtils.clamp(pomAngX, -0.6, 0.6), 0, THREE.MathUtils.clamp(pomAngZ, -0.6, 0.6)));
160	    pom.quaternion.copy(pomRest).multiply(qPom);
161	
162	    // blink (cartoon squash of the eyes); no blinking while dizzy
163	    blinkT -= dt;
164	    let blink = 1;
165	    if (expression !== 'dizzy') {
166	      if (blinkT < 0.14) blink = Math.abs(blinkT - 0.07) / 0.07;
167	      if (blinkT <= 0) blinkT = 2.2 + Math.random() * 2.6;
168	    }
169	    eyeL.scale.y = eyeR.scale.y = Math.max(0.08, blink);
170	
171	    for (const f of furs) {
172	      f.uniforms.uTime.value = st.time;
173	      f.uniforms.uWind.value.set(0, 0, -Math.min(0.6, st.speed / 25));
174	    }
175	  };
176	
177	  return { root, setExpression, update, radius: 0.8 };
178	}
