1	/**
2	 * Canvas-generated textures for Benny (no external downloads).
3	 * All colour maps are sRGB; normal maps are derived from height drawings (linear).
4	 */
5	import * as THREE from 'three';
6	
7	type Ctx = CanvasRenderingContext2D;
8	
9	function canvas(w: number, h: number): [HTMLCanvasElement, Ctx] {
10	  const c = document.createElement('canvas');
11	  c.width = w;
12	  c.height = h;
13	  return [c, c.getContext('2d')!];
14	}
15	
16	function colorTex(c: HTMLCanvasElement, wrap = false): THREE.CanvasTexture {
17	  const t = new THREE.CanvasTexture(c);
18	  t.colorSpace = THREE.SRGBColorSpace;
19	  t.anisotropy = 4;
20	  if (wrap) t.wrapS = THREE.RepeatWrapping;
21	  t.needsUpdate = true;
22	  return t;
23	}
24	
25	/** Sobel normal map from a grayscale height canvas */
26	function normalFromHeight(src: HTMLCanvasElement, strength: number, wrap = false): THREE.CanvasTexture {
27	  const w = src.width, h = src.height;
28	  const hd = src.getContext('2d')!.getImageData(0, 0, w, h).data;
29	  const [c, ctx] = canvas(w, h);
30	  const out = ctx.createImageData(w, h);
31	  const H = (x: number, y: number) => {
32	    x = wrap ? (x + w) % w : Math.min(w - 1, Math.max(0, x));
33	    y = Math.min(h - 1, Math.max(0, y));
34	    return hd[(y * w + x) * 4] / 255;
35	  };
36	  for (let y = 0; y < h; y++) {
37	    for (let x = 0; x < w; x++) {
38	      const dx = (H(x + 1, y - 1) + 2 * H(x + 1, y) + H(x + 1, y + 1)) - (H(x - 1, y - 1) + 2 * H(x - 1, y) + H(x - 1, y + 1));
39	      const dy = (H(x - 1, y + 1) + 2 * H(x, y + 1) + H(x + 1, y + 1)) - (H(x - 1, y - 1) + 2 * H(x, y - 1) + H(x + 1, y - 1));
40	      let nx = -dx * strength, ny = dy * strength, nz = 1;
41	      const l = Math.hypot(nx, ny, nz);
42	      nx /= l; ny /= l; nz /= l;
43	      const i = (y * w + x) * 4;
44	      out.data[i] = (nx * 0.5 + 0.5) * 255;
45	      out.data[i + 1] = (ny * 0.5 + 0.5) * 255;
46	      out.data[i + 2] = (nz * 0.5 + 0.5) * 255;
47	      out.data[i + 3] = 255;
48	    }
49	  }
50	  ctx.putImageData(out, 0, 0);
51	  const t = new THREE.CanvasTexture(c);
52	  t.colorSpace = THREE.NoColorSpace;
53	  if (wrap) t.wrapS = THREE.RepeatWrapping;
54	  t.needsUpdate = true;
55	  return t;
56	}
57	
58	export const BENNY_COLORS = {
59	  // knit purple of refs 04–10 (cuff #7513ED, pom #7F14EC measured in ref 05)
60	  purple: '#7a18f0',
61	  purpleDark: '#36098e',
62	  purpleLight: '#9d55ff',
63	  white: '#fffaff',
64	  whiteShade: '#bcadd0',
65	  brim: '#7513ed',
66	  brimDark: '#330887',
67	  // hot plush pink of refs 02–10 (ref 05 fur median #F64EB1; the live median read bluer at #FF4CC4)
68	  pinkRoot: '#e6468c',
69	  pinkTip: '#fd80b4',
70	  pinkSkin: '#e85498',
71	  pomRoot: '#4a08b4',
72	  pomTip: '#8f3cff',
73	  // star: warm yellow #F7BB19 (ref 05), not orange
74	  gold: '#ffc61c',
75	};
