77	/**
78	 * The crown texture tiles this many times around the beanie (lathe u is scaled by it in build.ts), so the
79	 * stitches stay small: 36 columns × 4 ≈ 144 stitch columns around, as in ref 05 (≈ 6 px stitches on a
80	 * 293 px wide cuff), within the 1024 px texture limit of the GLB export.
81	 */
82	export const CROWN_REPEAT = 4;
83	
84	/** stockinette stitch: two slanted loops forming a "V", colour + height */
85	function knitStitch(ctx: Ctx, hctx: Ctx, cx: number, cy: number, cw: number, rh: number, base: string, mid: string, shade: string) {
86	  for (const side of [-1, 1]) {
87	    const ex = cx + side * cw * 0.21;
88	    const g = ctx.createRadialGradient(ex - side * cw * 0.04, cy - rh * 0.18, 1, ex, cy, cw * 0.36);
89	    g.addColorStop(0, base);
90	    g.addColorStop(0.55, mid);
91	    g.addColorStop(1, shade);
92	    ctx.save();
93	    ctx.translate(ex, cy);
94	    ctx.rotate(side * -0.5);
95	    ctx.beginPath();
96	    ctx.ellipse(0, 0, cw * 0.2, rh * 0.6, 0, 0, Math.PI * 2);
97	    ctx.fillStyle = g;
98	    ctx.fill();
99	    ctx.restore();
100	    const hg = hctx.createRadialGradient(ex, cy, 0, ex, cy, cw * 0.3);
101	    hg.addColorStop(0, '#fff');
102	    hg.addColorStop(0.6, '#9a9a9a');
103	    hg.addColorStop(1, '#151515');
104	    hctx.save();
105	    hctx.translate(ex, cy);
106	    hctx.rotate(side * -0.5);
107	    hctx.beginPath();
108	    hctx.ellipse(0, 0, cw * 0.2, rh * 0.6, 0, 0, Math.PI * 2);
109	    hctx.fillStyle = hg;
110	    hctx.fill();
111	    hctx.restore();
112	  }
113	}
114	
115	/**
116	 * Knit crown texture (u = around, one of CROWN_REPEAT tiles; v = height 0 bottom → 1 top).
117	 * Stripes bottom→top: white, purple, white, purple, white; with the purple cuff that is 3 purple bands
118	 * (refs 04–10 rear: cuff · W · P · W, the top purple ring shows around the pom-pom, the white top is under it).
119	 */
120	export function knitCrownTextures(): { map: THREE.CanvasTexture; normalMap: THREE.CanvasTexture } {
121	  const W = 1024, Hh = 512;
122	  const [c, ctx] = canvas(W, Hh);
123	  const [hc, hctx] = canvas(W, Hh);
124	  const C = BENNY_COLORS;
125	  const stripes: [number, number, string, string, string][] = [
126	    // [v0, v1, highlight, base, groove]   (v measured from bottom)
127	    [0.0, 0.3, '#ffffff', C.white, C.whiteShade],
128	    [0.3, 0.55, C.purpleLight, C.purple, C.purpleDark],
129	    [0.55, 0.76, '#ffffff', C.white, C.whiteShade],
130	    [0.76, 0.92, C.purpleLight, C.purple, C.purpleDark],
131	    [0.92, 1.0, '#ffffff', C.white, C.whiteShade],
132	  ];
133	  hctx.fillStyle = '#000';
134	  hctx.fillRect(0, 0, W, Hh);
135	  const cols = 36;
136	  const cw = W / cols;
137	  const rowH = 30; // ≈ 0.025 units per stitch row on the 0.42-unit crown (stitches ≈ as tall as wide)
138	  for (const [v0, v1, hi, base, shade] of stripes) {
139	    const y0 = Hh * (1 - v1), y1 = Hh * (1 - v0);
140	    ctx.fillStyle = shade;
141	    ctx.fillRect(0, y0, W, y1 - y0);
142	    const rows = Math.max(1, Math.round((y1 - y0) / rowH));
143	    const rh = (y1 - y0) / rows;
144	    for (let r = 0; r < rows; r++) {
145	      for (let k = 0; k < cols; k++) knitStitch(ctx, hctx, k * cw + cw / 2, y0 + r * rh + rh / 2, cw, rh, hi, base, shade);
146	    }
147	    // fuzzy yarn speckle
148	    for (let i = 0; i < 3000; i++) {
149	      ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.1})`;
150	      ctx.fillRect(Math.random() * W, y0 + Math.random() * (y1 - y0), 1.5, 1.5);
151	    }
152	  }
153	  return { map: colorTex(c, true), normalMap: normalFromHeight(hc, 4.5, true) };
154	}
155	
156	/** Chunky ribbed (k2p2) folded cuff texture, u around, v across the band: deep grooves + stacked stitches */
157	export function ribbedBrimTextures(): { map: THREE.CanvasTexture; normalMap: THREE.CanvasTexture } {
158	  const W = 1024, Hh = 256;
159	  const [c, ctx] = canvas(W, Hh);
160	  const [hc, hctx] = canvas(W, Hh);
161	  const C = BENNY_COLORS;
162	  const ribs = 64; // ≈ 30 ribs across the visible half, as in ref 05
163	  const rw = W / ribs;
164	  for (let k = 0; k < ribs; k++) {
165	    const x = k * rw;
166	    const g = ctx.createLinearGradient(x, 0, x + rw, 0);
167	    g.addColorStop(0, C.brimDark);
168	    g.addColorStop(0.22, C.brim);
169	    g.addColorStop(0.5, C.purpleLight);
170	    g.addColorStop(0.78, C.brim);
171	    g.addColorStop(1, C.brimDark);
172	    ctx.fillStyle = g;
173	    ctx.fillRect(x, 0, rw, Hh);
174	    const hg = hctx.createLinearGradient(x, 0, x + rw, 0);
175	    hg.addColorStop(0, '#000');
176	    hg.addColorStop(0.5, '#fff');
177	    hg.addColorStop(1, '#000');
178	    hctx.fillStyle = hg;
179	    hctx.fillRect(x, 0, rw, Hh);
180	    // stacked knit "V" stitches along the rib
181	    const rows = 10;
182	    const rh = Hh / rows;
183	    for (let r = 0; r < rows; r++) {
184	      const cy = (r + 0.5) * rh;
185	      for (const side of [-1, 1]) {
186	        ctx.save();
187	        ctx.translate(x + rw / 2 + side * rw * 0.16, cy);
188	        ctx.rotate(side * -0.45);
189	        ctx.fillStyle = 'rgba(175,125,255,0.35)';
190	        ctx.beginPath();
191	        ctx.ellipse(0, 0, rw * 0.17, rh * 0.42, 0, 0, Math.PI * 2);
192	        ctx.fill();
193	        ctx.restore();
194	        hctx.save();
195	        hctx.translate(x + rw / 2 + side * rw * 0.16, cy);
196	        hctx.rotate(side * -0.45);
197	        hctx.fillStyle = 'rgba(255,255,255,0.4)';
198	        hctx.beginPath();
199	        hctx.ellipse(0, 0, rw * 0.17, rh * 0.42, 0, 0, Math.PI * 2);
200	        hctx.fill();
201	        hctx.restore();
202	      }
203	      // dark gap between stacked stitches
204	      ctx.fillStyle = 'rgba(30,0,80,0.35)';
205	      ctx.fillRect(x + rw * 0.2, cy + rh * 0.42, rw * 0.6, rh * 0.12);
206	    }
207	  }
208	  return { map: colorTex(c, true), normalMap: normalFromHeight(hc, 3.6, true) };
209	}
