211	/** Planar eye texture (centre of the canvas = centre of the eye dome). */
212	export function eyeTexture(kind: 'happy' | 'dizzy'): THREE.CanvasTexture {
213	  const S = 256;
214	  const [c, ctx] = canvas(S, S);
215	  const m = S / 2;
216	  // sclera
217	  const sg = ctx.createRadialGradient(m, m * 0.8, 10, m, m, m);
218	  sg.addColorStop(0, '#ffffff');
219	  sg.addColorStop(0.8, '#f3eefc');
220	  sg.addColorStop(1, '#b9a8d8');
221	  ctx.fillStyle = sg;
222	  ctx.fillRect(0, 0, S, S);
223	  if (kind === 'happy') {
224	    // big violet iris
225	    const ir = m * 0.8;
226	    const ig = ctx.createLinearGradient(0, m - ir, 0, m + ir);
227	    ig.addColorStop(0, '#2d0f73');
228	    ig.addColorStop(0.45, '#6a35d6');
229	    ig.addColorStop(1, '#c9a4ff');
230	    ctx.fillStyle = ig;
231	    ctx.beginPath();
232	    ctx.arc(m, m + 4, ir, 0, Math.PI * 2);
233	    ctx.fill();
234	    // iris radial streaks
235	    ctx.strokeStyle = 'rgba(255,255,255,0.10)';
236	    ctx.lineWidth = 2;
237	    for (let a = 0; a < Math.PI * 2; a += 0.18) {
238	      ctx.beginPath();
239	      ctx.moveTo(m + Math.cos(a) * ir * 0.45, m + 4 + Math.sin(a) * ir * 0.45);
240	      ctx.lineTo(m + Math.cos(a) * ir * 0.95, m + 4 + Math.sin(a) * ir * 0.95);
241	      ctx.stroke();
242	    }
243	    ctx.strokeStyle = '#1e0848';
244	    ctx.lineWidth = 7;
245	    ctx.beginPath();
246	    ctx.arc(m, m + 4, ir, 0, Math.PI * 2);
247	    ctx.stroke();
248	    // pupil
249	    ctx.fillStyle = '#10061f';
250	    ctx.beginPath();
251	    ctx.arc(m, m + 6, ir * 0.48, 0, Math.PI * 2);
252	    ctx.fill();
253	    // sparkles: big upper-right, small lower-left
254	    ctx.fillStyle = '#ffffff';
255	    ctx.beginPath();
256	    ctx.ellipse(m + ir * 0.32, m - ir * 0.3, ir * 0.24, ir * 0.2, -0.4, 0, Math.PI * 2);
257	    ctx.fill();
258	    ctx.beginPath();
259	    ctx.arc(m - ir * 0.3, m + ir * 0.38, ir * 0.11, 0, Math.PI * 2);
260	    ctx.fill();
261	    ctx.fillStyle = 'rgba(255,255,255,0.7)';
262	    ctx.beginPath();
263	    ctx.arc(m + ir * 0.05, m + ir * 0.5, ir * 0.06, 0, Math.PI * 2);
264	    ctx.fill();
265	  } else {
266	    // dizzy purple spiral
267	    ctx.strokeStyle = '#5a1fc8';
268	    ctx.lineWidth = 15;
269	    ctx.lineCap = 'round';
270	    ctx.beginPath();
271	    for (let t = 0; t < 6 * Math.PI; t += 0.05) {
272	      const r = (t / (6 * Math.PI)) * m * 0.82;
273	      const x = m + Math.cos(t) * r, y = m + Math.sin(t) * r;
274	      if (t === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
275	    }
276	    ctx.stroke();
277	    ctx.strokeStyle = '#8a55ff';
278	    ctx.lineWidth = 5;
279	    ctx.stroke();
280	  }
281	  // dark rim
282	  ctx.strokeStyle = '#3a1d66';
283	  ctx.lineWidth = 10;
284	  ctx.beginPath();
285	  ctx.arc(m, m, m - 5, 0, Math.PI * 2);
286	  ctx.stroke();
287	  return colorTex(c);
288	}
