290	/** Mouth decal (alpha). 'happy' = open smile, 'dizzy' = round open "O", 'peek' = small grin */
291	export function mouthTexture(kind: 'happy' | 'dizzy' | 'peek'): THREE.CanvasTexture {
292	  const S = 256;
293	  const [c, ctx] = canvas(S, S);
294	  ctx.clearRect(0, 0, S, S);
295	  const m = S / 2;
296	  ctx.save();
297	  ctx.beginPath();
298	  if (kind === 'dizzy') {
299	    ctx.ellipse(m, m, 62, 74, 0, 0, Math.PI * 2);
300	  } else {
301	    const w = kind === 'peek' ? 86 : 104;
302	    const d = kind === 'peek' ? 84 : 104;
303	    ctx.moveTo(m - w, m - 30);
304	    ctx.quadraticCurveTo(m, m - 16, m + w, m - 30);
305	    ctx.bezierCurveTo(m + w * 0.9, m + d * 0.9, m - w * 0.9, m + d * 0.9, m - w, m - 30);
306	  }
307	  ctx.closePath();
308	  ctx.fillStyle = '#5b0f2a';
309	  ctx.fill();
310	  ctx.clip();
311	  // tongue
312	  ctx.fillStyle = '#ff6f9c';
313	  ctx.beginPath();
314	  ctx.ellipse(m, kind === 'dizzy' ? m + 50 : m + 52, 58, 40, 0, 0, Math.PI * 2);
315	  ctx.fill();
316	  ctx.fillStyle = 'rgba(255,190,210,0.6)';
317	  ctx.beginPath();
318	  ctx.ellipse(m - 10, kind === 'dizzy' ? m + 36 : m + 38, 20, 9, -0.2, 0, Math.PI * 2);
319	  ctx.fill();
320	  ctx.restore();
321	  // lip line
322	  ctx.strokeStyle = '#7a1844';
323	  ctx.lineWidth = 7;
324	  ctx.lineJoin = 'round';
325	  ctx.stroke();
326	  const t = colorTex(c);
327	  return t;
328	}
