330	/** Soft blush disc (alpha) */
331	export function blushTexture(): THREE.CanvasTexture {
332	  const S = 128;
333	  const [c, ctx] = canvas(S, S);
334	  const g = ctx.createRadialGradient(S / 2, S / 2, 4, S / 2, S / 2, S / 2);
335	  g.addColorStop(0, 'rgba(255,70,130,0.95)');
336	  g.addColorStop(0.55, 'rgba(255,100,150,0.45)');
337	  g.addColorStop(1, 'rgba(255,120,170,0)');
338	  ctx.fillStyle = g;
339	  ctx.fillRect(0, 0, S, S);
340	  return colorTex(c);
341	}
