343	/** White paw sole with pink pads (planar, centre = centre of the sole) */
344	export function soleTexture(kind: 'foot' | 'hand'): THREE.CanvasTexture {
345	  const S = 256;
346	  const [c, ctx] = canvas(S, S);
347	  const m = S / 2;
348	  const sg = ctx.createRadialGradient(m, m, 10, m, m, m);
349	  sg.addColorStop(0, '#ffffff');
350	  sg.addColorStop(0.85, '#f8eef6');
351	  sg.addColorStop(1, '#e6cfe2');
352	  ctx.fillStyle = sg;
353	  ctx.fillRect(0, 0, S, S);
354	  const pad = (x: number, y: number, rx: number, ry: number) => {
355	    const g = ctx.createRadialGradient(x - rx * 0.3, y - ry * 0.3, 2, x, y, Math.max(rx, ry));
356	    g.addColorStop(0, '#ffb3cf');
357	    g.addColorStop(0.6, '#ff7fae');
358	    g.addColorStop(1, '#f2669b');
359	    ctx.fillStyle = g;
360	    ctx.beginPath();
361	    ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
362	    ctx.fill();
363	  };
364	  if (kind === 'foot') {
365	    pad(m, m + 26, 52, 44); // main pad
366	    pad(m - 58, m - 40, 20, 24);
367	    pad(m - 20, m - 66, 20, 24);
368	    pad(m + 20, m - 66, 20, 24);
369	    pad(m + 58, m - 40, 20, 24);
370	  } else {
371	    pad(m, m + 20, 44, 36);
372	    pad(m - 46, m - 34, 17, 20);
373	    pad(m, m - 56, 17, 20);
374	    pad(m + 46, m - 34, 17, 20);
375	  }
376	  return colorTex(c);
377	}
