"""Column / row colour-class runs through Benny.
usage: python3 -I runs.py IMG col X Y0 Y1      (vertical scan at x=X)
       python3 -I runs.py IMG row Y X0 X1      (horizontal scan at y=Y)
classes: P purple/violet knit, W white knit, F pink fur, Y star yellow, C cyan water, G gold coin/ring, . other
"""
import sys, colorsys
from PIL import Image


def cls(rgb):
    r, g, b = [c / 255 for c in rgb]
    h, s, v = colorsys.rgb_to_hsv(r, g, b)
    h *= 360
    if s < 0.22 and v > 0.72:
        return 'W'
    if 35 <= h <= 60 and s > 0.55 and v > 0.6:
        return 'Y'
    if 20 <= h < 35 and s > 0.6:
        return 'G'
    if 170 <= h <= 215 and s > 0.35:
        return 'C'
    if 245 <= h <= 292 and s > 0.35:
        return 'P'
    if (h >= 300 or h < 12) and s > 0.3 and v > 0.45:
        return 'F'
    return '.'


def runs(seq, off):
    out = []
    cur, start = None, 0
    for i, c in enumerate(seq):
        if c != cur:
            if cur is not None:
                out.append(f'{cur}{start + off}-{i - 1 + off}')
            cur, start = c, i
    out.append(f'{cur}{start + off}-{len(seq) - 1 + off}')
    return ' '.join(out)


if __name__ == '__main__':
    im = Image.open(sys.argv[1]).convert('RGB')
    mode = sys.argv[2]
    a, b0, b1 = map(int, sys.argv[3:6])
    if mode == 'col':
        seq = [cls(im.getpixel((a, y))) for y in range(b0, b1)]
    else:
        seq = [cls(im.getpixel((x, a))) for x in range(b0, b1)]
    print(runs(seq, b0))

