// usage (cwd = repo): node cap2.mjs OUTDIR [ids...] [--q=extra&query]
// For each id: real game capture (same as scripts/capture.mjs) → OUTDIR/NN.png, then Benny QA mask → OUTDIR/NN_mask.png
import { mkdirSync, writeFileSync } from 'node:fs';
import { loadPlaywright, CHROMIUM_ARGS, startVite } from '/home/user/rainbow-/scripts/lib/pw.mjs';
const args = process.argv.slice(2);
const out = args[0];
const q = (args.find((a) => a.startsWith('--q=')) ?? '').slice(4);
let ids = args.slice(1).filter((a) => !a.startsWith('--'));
if (!ids.length) ids = ['05'];
mkdirSync(out, { recursive: true });
const NATIVE = { '03': [727, 1536] };
const { chromium } = loadPlaywright();
const vite = await startVite(5331);
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const log = [];
try {
  for (const id of ids) {
    const [w, h] = NATIVE[id] ?? [864, 1536];
    const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
    const errs = [];
    page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
    page.on('pageerror', (e) => errs.push('pageerror ' + e.message));
    await page.goto(`${vite.url}/?qa=1&dpr=1${q ? '&' + q : ''}`);
    await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 240000 });
    const err = await page.evaluate(() => window.__error);
    if (err) throw new Error(err);
    await page.evaluate((cid) => window.__rainbow.goto(cid), id);
    await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => r())));
    await page.evaluate(() => document.fonts.ready);
    await page.waitForTimeout(250);
    await page.screenshot({ path: `${out}/${id}.png`, timeout: 180000 });
    const state = await page.evaluate(() => window.__rainbow.state());
    const bs = await page.evaluate(() => window.__rainbow.bennyScreen?.());
    const info = await page.evaluate(() => window.__bennyQA?.info());
    const stats = await page.evaluate(() => window.__rainbow.stats());
    await page.evaluate(() => window.__bennyQA?.mask(true));
    for (let i = 0; i < 3; i++) await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => r())));
    await page.waitForTimeout(150);
    await page.screenshot({ path: `${out}/${id}_mask.png`, timeout: 180000 });
    // camera elevation over Benny's body centre (angle between the view ray and Benny's horizontal plane)
    let elev = null;
    if (bs && info) {
      const c = bs.cam, b = info.body, u = info.up;
      const d = [c[0] - b[0], c[1] - b[1], c[2] - b[2]];
      const L = Math.hypot(...d);
      elev = +(Math.asin((d[0] * u[0] + d[1] * u[1] + d[2] * u[2]) / L) * 180 / Math.PI).toFixed(2);
      const fdot = -(d[0] * info.fwd[0] + d[1] * info.fwd[1] + d[2] * info.fwd[2]) / L;
      info.dist = +L.toFixed(3);
      info.behind = +fdot.toFixed(3);
    }
    const rec = { id, state, bennyScreen: bs, benny: info, elevDeg: elev, calls: stats.calls, tris: stats.triangles, errors: errs.slice(0, 5) };
    log.push(rec);
    console.log(JSON.stringify(rec));
    await page.close();
  }
} finally {
  writeFileSync(`${out}/cap_log.json`, JSON.stringify(log, null, 2));
  await browser.close();
  await vite.close();
}

